import React from "react";
import { Link, graphql } from "gatsby";
import { Search } from "lucide-react";
import Layout from "../components/layout/layout";
import PostCard from "../components/postCard";
import Category from "../components/category";
import TerminalButtonLabel from "../components/terminalButtonLabel";
import { SEO as Seo } from "../components/seo";
const pagePath = (n) => (n === 1 ? "/blog/" : `/blog/${n}/`);
export default function BlogList({
  data,
  pageContext: { currentPage, numPages },
}) {
  return (
    <Layout className="archive-page">
      <section className="page-intro enter">
        <div className="archive-intro-copy">
          <h1>Articles</h1>
          <p>Practical notes on firmware, embedded Linux, and building useful devices.</p>
        </div>
        <Link className="button secondary archive-search" to="/search/">
          <Search size={17} aria-hidden="true" /> <TerminalButtonLabel label="Search articles" prompt={false} />
        </Link>
      </section>
      <div className="archive-topics">
        <Category limit={5} allLabel="All articles" />
      </div>
      <section aria-labelledby="archive-title">
        <div className="archive-results-heading">
          <div className="heading-with-count">
            <h2 id="archive-title">All articles</h2>
            <span className="count-badge">
              {data.allMdx.totalCount}
              <span className="sr-only"> articles</span>
            </span>
          </div>
          <span>Newest first</span>
        </div>
        <PostCard nodes={data.allMdx.nodes} variant="archive" headingLevel="h3" />
      </section>
      {numPages > 1 && (
        <nav className="pagination" aria-label="Article pagination">
          {currentPage > 1 && (
            <Link rel="prev" to={pagePath(currentPage - 1)}>
              <span aria-hidden="true">←</span> Previous
            </Link>
          )}
          {Array.from({ length: numPages }, (_, i) => (
            <Link
              aria-current={currentPage === i + 1 ? "page" : undefined}
              aria-label={`Page ${i + 1}`}
              key={i}
              to={pagePath(i + 1)}
            >
              {i + 1}
            </Link>
          ))}
          {currentPage < numPages && (
            <Link rel="next" to={pagePath(currentPage + 1)}>
              Next <span aria-hidden="true">→</span>
            </Link>
          )}
        </nav>
      )}
    </Layout>
  );
}
export const query = graphql`
  query BlogArchive($skip: Int!, $limit: Int!) {
    allMdx(sort: { frontmatter: { date: DESC } }, limit: $limit, skip: $skip) {
      totalCount
      nodes {
        ...PostCardData
      }
    }
  }
`;
export const Head = ({ pageContext: { currentPage } }) => (
  <Seo
    title={currentPage === 1 ? "Articles" : `Articles · Page ${currentPage}`}
    description="Practical notes on firmware, embedded Linux, and building useful devices. Browse projects, tutorials, and discoveries from the workbench."
    pathname={pagePath(currentPage)}
  />
);
